// Creating reactive state variables
const count = ref(0)
const isActive = ref(false)

// Example async function with random delay
async function fetchMockData() {
  const delay = Math.random() * 2000;
  await new Promise(resolve => setTimeout(resolve, delay));
  return { id: 1, name: 'Mock User' };
}

// Example async handler
async function fetchData() {
  const result = await mockFetch();
  data.value = result;
}

// Example: async handler with request tracking
async function fetchData() {
  const requestId = Date.now();
  latestRequest.value = requestId;

  const result = await mockFetch();

  if (latestRequest.value === requestId) {
    data.value = result;
  }
}

// Example of race condition protection
const handleFetch = async () => {
  const requestId = Symbol('request')
  latestRequest.value = requestId

  const result = await mockFetch()

  if (latestRequest.value === requestId) {
    data.value = result
  }
}

